<template>
    <loading :loading="loading">
        <div ref="interfaceContainer" class="interface-container">
            <a-row >
                <a-col :span="interfaceShow ? 18 : 24">
                    <div class="interface-bg">
                        <copy-text :value="controllerName" placement="right">
                            <h1>
                                <span class="diy-cursor">{{controllerName}}</span>
                            </h1>
                        </copy-text>
                        <div class="interface-content-bg">
                            <div v-if="interfaceShow">
                                <a-descriptions class="interface-content" layout="vertical" bordered size="small"
                                                :key="inter.interfaceId + '_' + index"
                                                v-for="(inter, index) in interfaceList">
                                    <template #title>
                                        <div class="content-title">
                                            <h2>
                                                <copy-text :value="inter.interfaceName" placement="right">
                                                    <span style="padding: 0px 5px">{{getInterfaceIndex(index)}}</span>
                                                    <span class="diy-cursor" :id="'_' + inter.interfaceId">{{inter.interfaceName}}</span>
                                                </copy-text>
                                            </h2>
                                            <copy-text :value="buildCopyInterfaceData(inter)" class="editor-copy" pre-tip-value="点击复制接口数据">
                                                <a-icon type="copy"/>
                                            </copy-text>
                                        </div>
                                    </template>
                                    <a-descriptions-item :span="3">
                                        <template #label>
                                            <span style="padding-right: 20px">请求地址</span>
                                            <copy-text :value="reqType" placement="right" :key="inter.interfaceId + '_' + reqType" v-for="reqType in inter.requestTypeList">
                                                <a-tag color="orange" class="diy-cursor">
                                                    {{ reqType }}
                                                </a-tag>
                                            </copy-text>
                                        </template>
                                        <copy-text :value="uri" placement="right" :key="inter.interfaceId + '_' + uri" v-for="uri in inter.uriList">
                                            <span class="request-uri diy-cursor">{{uri}}</span>
                                        </copy-text>
                                    </a-descriptions-item>
                                    <a-descriptions-item :span="3" v-if="interfaceFormDataView(inter.formData) || inter.bodyData">
                                        <template #label>
                                            <span style="padding-right: 20px">请求参数</span>
                                            <copy-text :value="inter.requestContentType" placement="right">
                                                <a-tag color="orange" class="diy-cursor">
                                                    {{inter.requestContentType}}
                                                </a-tag>
                                            </copy-text>
                                        </template>
                                        <a-tabs class="content-tab" v-if="interfaceFormDataView(inter.formData)"
                                                default-active-key="1" size="small">
                                            <a-tab-pane key="1" tab="字段参数">
                                                <a-table
                                                    :pagination="false"
                                                    :columns="columns"
                                                    rowKey="name"
                                                    :data-source="inter.formData"
                                                    size="small"
                                                    :bordered="true"/>
                                            </a-tab-pane>
                                            <a-tab-pane key="2" tab="JSON示例">
                                                <div class="codeEditBox">
                                                    <code-viewer
                                                        :value="inter.formDataJson"
                                                        :options="{readOnly: true}"
                                                        language="json"
                                                    ></code-viewer>
                                                </div>
                                            </a-tab-pane>
                                            <a-tab-pane key="3" tab="JS Object">
                                                <div class="codeEditBox">
                                                    <code-viewer
                                                        :value="inter.formDataJsObj"
                                                        :options="{readOnly: true}"
                                                        language="javascript"
                                                    ></code-viewer>
                                                </div>
                                            </a-tab-pane>
                                        </a-tabs>
                                        <a-tabs class="content-tab" v-if="inter.bodyData" default-active-key="1" size="small">
                                            <a-tab-pane key="1" tab="JSON参数">
                                                <div class="codeEditBox">
                                                    <code-viewer
                                                        :value="inter.bodyData"
                                                        :options="{readOnly: true}"
                                                        language="json"
                                                    ></code-viewer>
                                                </div>
                                            </a-tab-pane>
                                            <a-tab-pane key="2" tab="JS Object">
                                                <div class="codeEditBox">
                                                    <code-viewer
                                                        :value="inter.bodyDataJsObj"
                                                        :options="{readOnly: true}"
                                                        language="javascript"
                                                    ></code-viewer>
                                                </div>
                                            </a-tab-pane>
                                        </a-tabs>
                                    </a-descriptions-item>
                                    <a-descriptions-item :span="3" v-if="inter.resData">
                                        <template #label>
                                            <span style="padding-right: 20px">响应示例</span>
                                            <copy-text value="application/json" placement="right">
                                                <a-tag color="orange" class="diy-cursor">
                                                    application/json
                                                </a-tag>
                                            </copy-text>
                                        </template>
                                        <a-tabs class="content-tab" default-active-key="1" size="small">
                                            <a-tab-pane v-if="inter.resData" key="1" tab="响应示例">
                                                <div class="codeEditBox">
                                                    <code-viewer
                                                        :value="inter.resData"
                                                        :options="{readOnly: true}"
                                                        language="json"
                                                    ></code-viewer>
                                                </div>
                                            </a-tab-pane>
                                            <a-tab-pane v-if="inter.resDataJsObj" key="2" tab="JS Object">
                                                <div class="codeEditBox">
                                                    <code-viewer
                                                        :value="inter.resDataJsObj"
                                                        :options="{readOnly: true}"
                                                        language="javascript"
                                                    ></code-viewer>
                                                </div>
                                            </a-tab-pane>
                                        </a-tabs>
                                    </a-descriptions-item>
                                </a-descriptions>
                            </div>
                            <div v-else>
                                <empty-box text="暂无接口数据"/>
                            </div>
                        </div>
                    </div>
                </a-col>
                <a-col :span="6" v-if="interfaceShow">
                    <div class="catalog-bg">
                        <div class="checkbox-bg" v-show="checkBoxShow">
                            <a-space direction="vertical">
                                <a-checkbox v-model="interfaceParams.hasComment" @change="checkEnabled">
                                    显示注释
                                </a-checkbox>
                                <a-checkbox v-model="interfaceParams.hasType" :disabled="disabledStatus.hasType"
                                            @change="getInterfaceList">
                                    显示类型
                                </a-checkbox>
                                <a-checkbox v-model="interfaceParams.hasValid" :disabled="disabledStatus.hasValid"
                                            @change="getInterfaceList">
                                    显示验证
                                </a-checkbox>
                                <a-checkbox v-model="interfaceParams.addDefaultValue" @change="getInterfaceList">
                                    显示默认值
                                </a-checkbox>
                            </a-space>
                        </div>
                        <a-anchor :affix="false" :offsetTop="200" style="min-width: 1px" :getContainer="getContainer" @change="handleAnchor" wrapperClass="anchor-box">
                            <a-anchor-link v-for="(item, index) in interfaceList"
                                           :href="'#_' + item.interfaceId"
                                           :key="getInterfaceIndex(index)"
                                           :title="getInterfaceIndex(index) + ' ' + item.interfaceName"/>
                        </a-anchor>
                    </div>
                </a-col>
            </a-row>
            <div>
                <a-back-top :target="getContainer" />
            </div>
        </div>
    </loading>
</template>

<script>

import {listInterface} from "@/api/docs"

export default {
    name: "index",
    data() {
        return {
            controllerName: '',
            loading: false,
            interfaceList: [],
            interfaceShow: false,
            checkBoxShow: false,
            interfaceParams: {
                docsConfigId: '',
                createTime: '',
                controllerId: '',
                // 是否有注释
                hasComment: true,
                // 是否有类型
                hasType: true,
                // 是否有验证
                hasValid: true,
                // 是否有默认值
                addDefaultValue: true
            },
            disabledStatus: {
                hasValid: false,
                hasType: false
            },
            columns: [
                {
                    title: '名称',
                    dataIndex: 'name',
                    width: 150
                },
                {
                    title: '类型',
                    dataIndex: 'type',
                    width: 100
                },
                {
                    title: '验证',
                    dataIndex: 'validation',
                    width: 100
                },
                {
                    title: '描述',
                    dataIndex: 'comment',
                },
            ],
        }
    },
    methods: {

        // 初始化
        init(docsConfigId, createTime, controllerId, controllerName) {
            this.controllerName = controllerName ? controllerName : '未知接口分组'
            if (!docsConfigId || !createTime || !controllerId) {
                this.interfaceShow = false
                return
            }
            this.interfaceParams.docsConfigId = docsConfigId
            this.interfaceParams.createTime = createTime
            this.interfaceParams.controllerId = controllerId
            this.getInterfaceList()
        },

        // 获取接口数据
        getInterfaceList() {
            this.checkBoxShow = false
            this.interfaceList = []
            this.loading = true
            listInterface(this.interfaceParams).then(res => {
                if (res.code == 200 && res.data && res.data.length > 0) {
                    this.interfaceList = res.data
                    this.interfaceShow = true
                    this.checkBoxShow = true
                    this.$nextTick(()=> {
                        this.getContainer().scrollTop = 0
                        this.scrollToAnchor()
                    })
                    return
                }
                this.interfaceShow = false
            }).finally(()=> {
                this.loading = false
            })
        },

        // 滚动到锚点
        scrollToAnchor() {
            // 获取URL中的锚点
            const hash = this.$route.hash
            // 如果存在锚点
            if (hash) {
                // 获取对应锚点的DOM元素
                const anchorElement = document.querySelector(hash)
                // 如果找到了对应的元素
                if (anchorElement) {
                    // 滚动到该元素位置
                    anchorElement.scrollIntoView({ behavior: 'auto', block: 'start', inline: 'nearest' })
                    this.getContainer().scrollBy(0, -200)
                }
            }
        },

        // 锚点改变
        handleAnchor(e) {
            localStorage.setItem("currentMenuItemKey", this.interfaceParams.controllerId + e)
            if (e && this.$route.hash !== e) {
                this.$router.push({
                    hash: e
                })
            }
        },

        // 表单参数是否可见
        interfaceFormDataView(formData) {
            return formData && formData.length > 0
        },

        // 获取接口序号
        getInterfaceIndex(index) {
            const i = index + 1
            return i > 9 ? i : (this.interfaceList.length > 99 ? '00' : '0') + i
        },

        // 触发显示注释
        checkEnabled() {
            const check = this.interfaceParams.hasComment
            this.interfaceParams.hasType = check
            this.interfaceParams.hasValid = check
            this.disabledStatus.hasType = !check
            this.disabledStatus.hasValid = !check
            this.getInterfaceList()
            return check
        },

        // 获取滚动容器
        getContainer() {
            return this.$refs['interfaceContainer']
        },
        // 构建复制接口数据
        buildCopyInterfaceData(item) {
            const reqTypes = (item.requestTypeList || []).join(",");
            const uriLines = (item.uriList || []).map(v => " - " + v).join("\n");
            const contentType = item.requestContentType || "未知";
            const queryJson = item.formDataJson ?? "";
            const bodyJson = item.bodyData ?? "";
            const resJson = item.resData ?? "";
            const name = item.interfaceName || "未命名接口";

            const paramArray = []
            if (!this.isEmptyStr(queryJson)) {
                paramArray.push(' - query：')
                paramArray.push(queryJson)
            }
            if (!this.isEmptyStr(bodyJson)) {
                paramArray.push(' - body：')
                paramArray.push(bodyJson)
            }

            return [
                `接口名称：${name}`,
                `请求地址[${reqTypes}]：`,
                uriLines,
                `请求参数[${contentType}]：`,
                paramArray.join("\n"),
                `响应示例[application/json]：`,
                resJson
            ].join("\n");
        },
        // 判断你接口数据字符串是否为空
        isEmptyStr(val) {
            if (!val) return true;
            const str = String(val).trim();
            return str === "" || str === "{}" || str === "[]";
        }
    }
}
</script>

<style scoped lang="less">
.interface-container {
    overflow-y: auto;
    height: calc(100vh - 64px);
}
.interface-bg {
    width: 800px;
    height: auto;
    background: #fff;
    margin: 30px auto 50px auto;
    box-shadow: rgba(0, 0, 0, 0.06) 0px 0px 10px 0px, rgba(0, 0, 0, 0.04) 0px 0px 0px 1px;
    padding: 50px;
    .interface-content-bg {
        margin-top: 40px;
        min-height: calc(100vh - 310px);
        position: relative;
    }
    .interface-content {
        margin-bottom: 40px;
        .content-title {
            display: flex;
            align-items: center;
            justify-content: space-between;
        }
    }
    .request-uri {
        font-size: 1.1em;
    }
    .content-tab {
        margin-bottom: 10px;
    }
}
.catalog-bg {
    position: fixed;
    width: 100%;
    .checkbox-bg {
        margin-top: 50px;
        min-width: 200px;
    }
    .anchor-box {
        margin-top: 40px;
        height: calc(100vh - 330px);
        width: 100%;
        position: relative;
        /deep/ .ant-anchor-ink-ball {
            display: inline-block!important;
        }
    }
}

h1 {
    font-family: "Oxygen", "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-weight: 500;
    line-height: 1.1;
    color: #1d365d;
    font-size: 28px;
    margin: 0;
}

.editor-copy {
    color: #999;
    font-size: .8rem;
    font-weight: 600;
    line-height: 15px;
    padding: 5px;
    margin: 0 5px;
    border-radius: 2px;
    user-select: none;
    transition:  all .2s;
    cursor: pointer;
}
.editor-copy:hover {
    background-color: #eee;
    color: #666;
}

</style>
